long long solve(const long long *values, int n) {
  if (n < 2) return 0;
  long long crossings = values[0];
  long long low = 0, high = 0;
  for (int i = 1; i < n; i++) {
    if (values[i] > low) low = values[i];
    high += values[i];
  }
  while (low < high) {
    long long mid = low + (high - low) / 2;
    long long used = 1, load = 0;
    for (int i = 1; i < n; i++) {
      if (load + values[i] > mid) { used++; load = values[i]; }
      else load += values[i];
    }
    if (used <= crossings) high = mid;
    else low = mid + 1;
  }
  return low;
}

